mapper.select:
SELECT ir.id, ir.drug_id, d.drug_code, d.drug_name, ir.inventory_id, i.batch_no, ir.record_type, ir.quantity_change, ir.before_quantity, ir.after_quantity, ir.biz_no, ir.operator_name, ir.remark, ir.operated_at FROM inventory_record ir INNER JOIN drug d ON d.id = ir.drug_id INNER JOIN inventory i ON i.id = ir.inventory_id WHERE ir.deleted = 0 AND d.deleted = 0 AND i.deleted = 0
AND ir.drug_id = #{drugId}
AND ir.record_type = #{recordType}
AND ir.biz_no = #{bizNo}
ORDER BY ir.operated_at DESC, ir.id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(1)
FROM inventory_record ir
INNER JOIN drug d ON d.id = ir.drug_id
INNER JOIN inventory i ON i.id = ir.inventory_id
WHERE ir.deleted = 0
  AND d.deleted = 0
  AND i.deleted = 0

    AND ir.drug_id = #{drugId}


    AND ir.record_type = #{recordType}


    AND ir.biz_no = #{bizNo}
